export default function(component) {
  const {data:d, parentElement, setTriggerValue} = component;
  const root = parentElement.querySelector('#groww-workspace');
  if (!root || !d) return;
  const ui = root._ui || (root._ui = {nav: d.outputs ? 'results' : 'upload', tab:'pulse', drawer:null, evidenceTab:'reviews', editing:false, draft:'', restoreTried:false, lastDownload:null, searchTimer:null, periodDirty:false});
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num = value => value == null ? '—' : Number(value).toLocaleString('en-IN');
  const date = value => value ? new Date(value+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}) : 'Not available';
  const bytes = n => n > 1024*1024 ? (n/(1024*1024)).toFixed(1)+' MB' : Math.ceil(n/1024)+' KB';
  const link = value => {try {const u=new URL(value);return u.protocol==='https:'?esc(u.href):'#';}catch{return '#';}};
  const icons = {
    chart:'<path d="m4 14 4-6 4 3 6-7M4 5v3m14 10 3 3"/><circle cx="16" cy="16" r="4"/><path d="M3 19v-3M13 4V2"/>',
    file:'<path d="M6 3h8l4 4v14H6zM14 3v5h5M9 12h6M9 16h6"/>',
    table:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M4 9h16M10 9v12M14 9v12M7 6h10"/>',
    calendar:'<rect x="4" y="5" width="16" height="16" rx="1"/><path d="M8 3v4M16 3v4M4 10h16"/>',
    upload:'<path d="M7 17H5a4 4 0 0 1-.4-8A7 7 0 0 1 18 7a5 5 0 0 1 1 10h-2M12 20V9m-4 4 4-4 4 4"/>',
    download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',
    arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
    swap:'<path d="M4 8h15m-4-4 4 4-4 4M20 16H5m4-4-4 4 4 4"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 11-2l3 4M18 17a7 7 0 0 1-11 2l-3-4"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',
    light:'<path d="M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0l-1 4H9zM12 5v3m-3 3h6"/>',
    filter:'<path d="M4 4h16l-6 7v8l-4-2v-6zM3 3l18 18"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
    lock:'<rect x="5" y="10" width="14" height="11" rx="1"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
    mail:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="m3 6 9 7 9-7"/>',
    copy:'<rect x="8" y="8" width="12" height="13" rx="1"/><path d="M16 8V3H3v13h5"/>',
    edit:'<path d="m4 17-1 4 4-1L20 7l-3-3zM15 6l3 3"/>',
    external:'<path d="M14 3h7v7m0-7L10 14M11 4H4v17h17v-7"/>',
    user:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-4a7 7 0 0 1 14 0v4z"/>',
    close:'<path d="m6 6 12 12M18 6 6 18"/>',
    search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
    rupee:'<path d="M6 4h13M6 8h13M7 4c9 0 9 8 0 8l9 8"/>',
    fingerprint:'<path d="M5 12a7 7 0 0 1 14 0M8 15v-3a4 4 0 0 1 8 0v5M11 20v-8a1 1 0 0 1 2 0v9M5 15v3M19 15v2M8 18v3"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',
    sparkle:'<path d="m12 3 2 6 6 3-6 2-2 7-3-7-6-2 6-3zM20 3v4m-2-2h4"/>',
    eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',
    hourglass:'<path d="M6 3h12M6 21h12M7 3v5l10 8v5M17 3v5L7 16v5"/>',
    folder:'<path d="M3 7V4h7l2 3h9v14H3zM3 11h18"/>',
    terminal:'<rect x="3" y="4" width="18" height="16" rx="1"/><path d="m7 8 3 4-3 4M13 16h4"/>',
    code:'<path d="m8 6-6 6 6 6M16 6l6 6-6 6"/>'
  };
  const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.file}</svg>`;
  const btn = (label, action, cls='', ico='', attrs='') => `<button class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
  const badge = (text, cls='') => `<span class="badge ${cls}">${text}</span>`;
  const anchor = (label, url, cls='btn ghost', ico='external') => `<a class="${cls}" href="${link(url)}" target="_blank" rel="noopener noreferrer">${ico?icon(ico):''}${esc(label)}</a>`;
  const scrollTop = () => {document.querySelector('[data-testid="stMain"]')?.scrollTo({top:0,behavior:'smooth'});window.scrollTo({top:0,behavior:'smooth'});};
  const emit = (type,payload={}) => setTriggerValue('action',{id:crypto.randomUUID(),type,payload});
  const toast = text => {root.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=text;root.append(e);setTimeout(()=>e.remove(),3000);};
  const download = (name, content, mime='text/plain') => {const u=URL.createObjectURL(new Blob([content],{type:mime+';charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);};
  const note = (text, cls='', ico='info') => `<div class="notice ${cls}">${icon(ico)}<span>${esc(text)}</span></div>`;
  const markdown = text => {
    const lines=String(text || '').split('\n');let html='',ol=false;
    const inline=s=>esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
    for(const line of lines){
      const item=line.match(/^\d+\.\s+(.+)/);
      if(item){if(!ol){html+='<ol class="action-list">';ol=true;}html+=`<li><span class="number">${(html.match(/class="number"/g)||[]).length+1}</span><span>${inline(item[1])}</span></li>`;continue;}
      if(ol){html+='</ol>';ol=false;}
      if(line.startsWith('## '))html+=`<h2>${inline(line.slice(3))}</h2>`;
      else if(line.startsWith('# '))html+=`<h1>${inline(line.slice(2))}</h1>`;
      else if(line.startsWith('> '))html+=`<blockquote>${inline(line.slice(2))}</blockquote>`;
      else if(line.trim())html+=`<p>${inline(line)}</p>`;
    }
    return html+(ol?'</ol>':'');
  };
  const periodText = `${date(d.period.start)} – ${date(d.period.end)}`;
  const a=d.analysis, o=d.outputs, x=d.execution, m=d.metrics, audit=d.audit;
  const shortDescription = text => {const first=String(text||'').split(/(?<=[.!?])\s+/)[0];return first.length>220?first.slice(0,220).replace(/\s+\S*$/,'')+'…':first;};
  const themeName = id => a?.themes.find(t=>t.id===id)?.name || 'Customer feedback';
  const exclusions = audit.excluded_count || 0;
  const selectedPeriod = () => ({start:root.querySelector('#start-date')?.value || d.period.start,end:root.querySelector('#end-date')?.value || d.period.end});

  // An opaque, same-browser workspace reference restores in-flight work after a refresh.
  // No credentials, uploaded CSV, or output text are persisted in browser storage. Download nonces prevent duplicate browser downloads after refresh.
  if(!ui.restoreTried){
    ui.restoreTried=true;
    try{const prior=sessionStorage.getItem('groww-workspace-live-v1');if(prior && prior!==d.workspace_id){emit('restore',{workspace_id:prior});root.innerHTML='<div class="empty">Reconnecting to your review workspace…</div>';return;}}catch{}
  }
  try{sessionStorage.setItem('groww-workspace-live-v1',d.workspace_id);}catch{}
  if(ui.lastWorkspace!==d.workspace_id){ui.lastWorkspace=d.workspace_id;ui.nav=o?'results':'upload';ui.editing=false;ui.drawer=null;}
  if(ui.previousStatus==='processing' && d.status==='ready' && ui.nav==='upload')ui.nav='results';
  if(ui.awaitingResults && d.status==='ready'){ui.nav='results';ui.awaitingResults=false;}
  ui.previousStatus=d.status;
  const signature=JSON.stringify(d);
  if(ui.signature===signature && !ui.forceRender)return;
  ui.signature=signature;ui.forceRender=false;

  function header(){return `<header class="topbar">
    <div class="brand"><div class="brand-logo">${icon('chart')}</div><span class="brand-name">Groww</span><div class="brand-sub">Review Intelligence<span>Turn customer reviews into a weekly product update</span></div></div>
    <nav class="navigation" aria-label="Workspace"><button data-nav="results" class="${ui.nav==='results'?'active':''}" aria-current="${ui.nav==='results'?'page':'false'}">Results Workspace</button><button data-nav="upload" class="${ui.nav==='upload'?'active':''}" aria-current="${ui.nav==='upload'?'page':'false'}">Upload &amp; Processing</button><button data-nav="audit" class="${ui.nav==='audit'?'active':''}" aria-current="${ui.nav==='audit'?'page':'false'}">Data Quality &amp; Audit</button></nav>
    <div class="top-actions"><span class="connection"><i class="dot ${d.connection!=='Configured'?'grey':''}"></i>${esc(d.connection)}</span><button class="profile" data-action="about" aria-label="Workspace information">${icon('user')}</button></div>
  </header>`;}
  function footer(){return `<footer class="footer"><div><strong>GROWW INTELLIGENCE ENGINE</strong><span class="separator">•</span>Customer feedback, evidence and product communication</div><div>Human approval before external writes<span class="separator">•</span>Unsent drafts only</div></footer>`;}
  function datasetBar(){return `<section class="dataset-bar"><div class="grow"><div class="dataset-meta"><span class="file-tag">${icon('table')}${esc(d.file.name)}<span class="badge">Active</span></span><span class="row">${icon('calendar')}${periodText} ${badge(d.period.weeks+' weeks')}</span><span class="row">${icon('refresh')}Data through: <strong>${date(m.data_cutoff)}</strong></span></div><div class="status">${badge('<i class="dot"></i>'+(x.completed?'Outputs saved':d.status==='ready'?'Analysis ready':d.status==='blocked'?'Evidence check needs attention':d.status==='processing'?'Analysis in progress':'Reviews loaded'),'mint')}</div></div><div class="dataset-actions">${btn('Change dataset','change_dataset','','swap',x.saving?'disabled':'')}${btn('Start new analysis','new','','refresh',x.saving?'disabled':'')}</div></section>`;}
  function metrics(){
    const vals=[['Valid reviews',num(m.included_count),'Unique valid reviews in the selected window','table',m.included_count!=null?'In scope':'Waiting'],['Useful feedback',num(m.useful_count),'Eligible for theme and quote analysis','light',m.useful_count!=null&&m.included_count?((m.useful_count/m.included_count)*100).toFixed(1)+'% yield':'Analyzing'],['Nonspecific feedback',num(m.nonspecific_count),'Retained for counts, excluded from themes','filter',m.nonspecific_count!=null&&m.included_count?((m.nonspecific_count/m.included_count)*100).toFixed(1)+'%':'Analyzing'],['Reporting coverage',d.period.weeks+' Weeks',m.coverage_start?date(m.coverage_start)+' – '+date(m.data_cutoff):'No reviews in selected period','calendar','Selected window']];
    return `<section class="metrics">${vals.map((v,i)=>`<div class="metric"><div class="row between"><span class="eyebrow">${v[0]}</span>${icon(v[3])}</div><div class="row wrap"><span class="metric-value">${v[1]}</span>${badge(esc(v[4]),i<2?'mint':'')}</div><p class="metric-note">${esc(v[2])}</p></div>`).join('')}</section><div class="audit-strip"><span class="row">${icon('shield')}Audit trace: <strong>${num(exclusions)} excluded rows</strong> before theme analysis.</span><button data-nav="audit">Review excluded rows (${num(audit.counts.duplicate)} duplicates · ${num(audit.counts.invalid)} invalid · ${num(audit.counts.outside+audit.counts.future)} outside window) →</button></div>`;
  }
  function themes(){return `<section class="card"><div class="card-header"><div><div class="row"><span class="eyebrow">Priority clustering</span>${badge('Up to 5 themes','mint')}</div><h2>Ranked Friction Themes</h2></div><span class="small muted">Sorted by review volume</span></div><div class="theme-list">${a.themes.map((t,i)=>{
    const negative=t.sentiment.negative||0,total=Object.values(t.sentiment).reduce((s,n)=>s+n,0),negativePct=total?Math.round(100*negative/total):0;
    const mood=negativePct>=50?`${negativePct}% negative`:Object.entries(t.sentiment).sort((p,q)=>q[1]-p[1])[0]?.[0]||'';
    return `<button class="theme" data-theme="${esc(t.id)}" aria-label="View supporting reviews for ${esc(t.name)}"><span class="rank">${i+1}</span><span class="grow"><span class="title-row"><h3>${esc(t.name)}</h3><span class="theme-tags"><span>${num(t.count)} reviews</span><span class="${negativePct>=50?'negative':''}">${esc(mood)}</span></span></span><p>${esc(shortDescription(t.description))}</p></span></button>`;
  }).join('')}</div><p class="theme-foot">Each useful review contributes to one primary theme. The top three are highlighted.</p></section>`;}
  function feeCard(){return `<section class="card fee-card"><div class="card-header"><div class="row"><div class="icon-box">${icon('rupee')}</div><div><div class="section-label">Review-derived fee issue</div><h2>Recurring Fee Confusion: ${esc(a.fee_name||'Not established')}</h2></div></div>${badge(o?'Sources checked':a.fee_name?'Sources pending':'Evidence needed',o?'mint':'amber')}</div>${a.fee_issue?`<div class="fee-data"><div><span class="eyebrow">Identified misunderstanding</span><h4>${esc(a.fee_issue)}</h4></div><div><span class="eyebrow">Independent supporting evidence</span><h4>${num(a.fee_evidence.length)} distinct review texts</h4><p>Exact fee passages from original customer reviews.</p></div></div><div class="fee-source"><p>${icon('shield')}${o?'Fee facts are grounded in two official Groww sources. Customer reports establish the confusion.':'Official fee information has not yet been verified.'}</p>${btn(o?'View Fee Evidence &amp; 2 Official Sources':'View Fee Evidence','fee_evidence','dark tiny','external')}</div>`:note('A recurring named fee requires at least three distinct supporting review texts. No fee explanation or external save is available.','amber') }</section>`;}
  function quoteCard(q){return `<article class="quote"><div class="meta"><span><span class="id">${esc(q.review_key)}</span> · ${date(q.date)}</span>${badge('Theme: '+esc(themeName(q.theme_id)))}</div><blockquote>“${esc(q.text)}”</blockquote>${q.source_url?anchor('View original source',q.source_url,'','external'):''}</article>`;}
  function quotes(){return `<section class="card"><div class="card-header"><div><span class="eyebrow">Verbatim corpus</span><h2>Traceable Customer Quotes</h2></div><span class="small muted">Original review wording</span></div>${a.quotes.length?a.quotes.map(quoteCard).join(''):note('Quote selection is unavailable until the evidence checks pass.','amber')}</section>`;}
  function feeOutput(){return `<h2>Question from customer feedback</h2><h1>${esc(o.fee_question)}</h1><p class="small muted space-top">Based on ${num(a?.fee_evidence.length||0)} distinct review texts.</p><h2>Answer</h2><ul>${o.fee_bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><h2>Official sources</h2>${o.sources.map(s=>`<a class="source" href="${link(s.url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(s.title)}</strong><br><span class="muted">${esc(new URL(s.url).hostname)} ${icon('external')}</span></a>`).join('')}<p><strong>Last checked: ${esc(o.last_checked)}</strong></p>`;}
  function emailOutput(){return `<div class="email-head"><div class="row"><span class="email-label">To</span><span>— Recipient left blank</span></div><div class="row"><span class="email-label">Subject</span><strong>${esc(o.email.subject)}</strong></div>${badge('Unsent draft · No automatic sending','mint')}</div><div class="email-body">${esc(o.email.body)}</div>`;}
  function outputTools(){const name=ui.tab==='pulse'?'weekly_product_pulse.md':ui.tab==='fee'?'fee_faq.md':'email_draft_preview.txt';return `<div class="output-tools"><span class="muted">${ui.tab==='email'?'Plain text · Unsent draft':'Format: Markdown'}</span><div>${btn('Copy','copy','tiny','copy')}${ui.tab==='pulse'&&o.can_edit?btn('Edit','edit','tiny','edit'):''}${btn(ui.tab==='email'?'Export .TXT':'Export .MD','export','tiny','download',`data-file="${name}" ${o.valid?'':'disabled'}`)}</div></div>`;}
  function outputPanel(){return `<section class="card"><div class="card-header"><div><span class="eyebrow">Automated synthesis</span><h2>Deliverable Outputs</h2></div>${badge(ui.tab==='fee'?o.fee_bullets.length+' / 6 bullets':ui.tab==='email'?'Unsent draft':o.word_count+' / 250 words'+(o.valid?' (Valid)':''),o.valid?'':'red')}</div><div class="output-tabs" role="tablist" aria-label="Generated outputs">${[['pulse','Weekly Product<br>Pulse'],['fee','Frequently Asked<br>Fee Question'],['email','Gmail Draft<br>Preview']].map(([id,label])=>`<button role="tab" aria-selected="${ui.tab===id}" data-output="${id}" class="${ui.tab===id?'active':''}">${label}</button>`).join('')}</div>${!o.valid?`<div class="required-status">${esc(o.validation_error)}</div>`:''}${o.edited&&!x.completed?note('Changes require fresh approval.','mint'):''}<div class="output-body" role="tabpanel">${ui.editing&&ui.tab==='pulse'?`<div class="editor-status" id="editor-count">${ui.draft.trim().split(/\s+/).filter(Boolean).length}/250 words</div><textarea class="editor" id="pulse-editor" aria-label="Weekly product pulse editor">${esc(ui.draft)}</textarea><div class="editor-tools">${btn('Cancel','cancel_edit')}${btn('Save changes','save_edit','dark')}</div><p class="small muted space-top">Keep the required headings, all three original quotes, and exactly three product actions.</p>`:(ui.tab==='pulse'?markdown(o.weekly_pulse):ui.tab==='fee'?feeOutput():emailOutput())+outputTools()}</div><details><summary>More exports and output options</summary><div class="detail-inner"><div class="row wrap">${btn('Document entry JSON','download','tiny','download','data-kind="document_entry.json"')}${btn('Complete analysis','download','tiny','download','data-kind="latest.json"')}${btn('Fee source passages','download','tiny','download','data-kind="fee_claim_evidence.md"')}${o.can_edit&&!ui.editing?btn('Regenerate outputs','regenerate','tiny','refresh'):''}</div></div></details></section>`;}
  function actionCard(action){const r=x.states[action],doc=action==='append_product_update',done=r?.status==='succeeded';const unknown=r?.status==='unknown'||r?.status==='in_progress';let title=doc?'Document saved':'Email draft created';if(!done)title=doc?'Document append':r?'Email draft not confirmed':'Email draft not started';return `<div class="completion"><div class="row"><span class="status-icon">${icon(done?'check':unknown?'clock':'info')}</span><div><h3>${title}</h3>${badge(done?'Completed':unknown?'Needs reconciliation':r?.status==='failed'?'Failed':'Waiting',done?'mint':'amber')}</div></div><p>${done?(doc?'The approved entry was appended to the configured Google Doc.':'The approved content was saved as an unsent Gmail draft. The recipient is blank.'):esc(r?.message||'This action runs after the document append is confirmed.')}</p>${done?anchor(doc?'Open saved document':'Open Gmail Drafts',doc?r.document_url:'https://mail.google.com/mail/u/0/#drafts','btn ghost tiny','external'):''}</div>`;}
  function approval(){
    const state=x.completed?'Saved successfully':x.saving?'Saving approved outputs':x.uncertain?'Checking save outcome':x.rejected?'Rejected':!o?.valid?'Output needs correction':'Awaiting approval';
    let body='';
    if(x.completed||Object.keys(x.states).length||x.saving){body=actionCard('append_product_update')+actionCard('create_support_draft');if(!x.snapshot_matches_receipts&&Object.keys(x.states).length)body+=note('Saved action records refer to an earlier destination or content snapshot. Completed actions are retained; review the saved result before continuing.','amber');if(x.saving)body+=note('Checking the approved save result. Repeated approval clicks are disabled.','mint','clock');else if(x.uncertain)body+=note('The previous write outcome is uncertain. Check the remote result before retrying.','amber')+btn('Check save result','reconcile','block','refresh');else if(x.retryable)body+=btn('Approve and retry remaining action','retry_save','primary block','refresh');}
    else body=`<p class="small muted">Review the destinations and approve the exact content displayed above.</p><div class="destinations"><div class="destination">${icon('file')}<div><strong>Destination 1: Google Docs</strong><p>Append the structured weekly product update.</p>${x.doc_url?anchor('Open configured document',x.doc_url,'','external'):'<span class="red">Document destination is not configured.</span>'}</div></div><div class="destination">${icon('mail')}<div><strong>Destination 2: Gmail Unsent Draft</strong><p>Recipient: [Blank] · Email will NOT be sent automatically.</p></div></div></div>${x.rejected?note('Rejected — no external actions were performed.','amber'):''}${x.destination_error?note('Saving is unavailable: '+x.destination_error,'amber'):''}${ui.editing||ui.periodDirty?note('Save or cancel pending changes before approving.','amber'):''}${btn('Approve and Save','approve','primary block','user',x.can_approve&&!ui.editing&&!ui.periodDirty?'':'disabled')}${btn('Reject (No External Writes)','reject','block','close',!o?.valid?'disabled':'')}<p class="approval-foot">${icon('lock')}Any content edit requires fresh approval.</p>`;
    return `<section class="card approval"><div class="card-header"><div class="row"><span class="icon-box">${icon('shield')}</span><div><span class="eyebrow">Human approval gate</span><h3>${x.completed?'Approved Outputs Saved':'Save Approved Outputs'}</h3></div></div>${badge(state,x.completed?'mint':x.uncertain?'amber':'')}</div>${body}${x.error?note(x.error,'error'):''}${Object.keys(x.states).length?`<details><summary>Execution details</summary><div class="detail-inner">${Object.entries(x.states).map(([k,r])=>`<div class="detail-row"><span>${k==='append_product_update'?'Google Docs':'Gmail draft'}</span><strong>${esc(r.status)}</strong></div>${r.completed_at?`<p class="mono">Completed: ${esc(r.completed_at)}</p>`:''}${r.draft_id?`<p class="mono">Draft ID: ${esc(r.draft_id)}</p>`:''}`).join('')}<div class="space-top">${btn('Download execution record','download','tiny','download','data-kind="receipts"')}</div></div></details>`:''}</section>`;
  }
  function errorPanel(){if(!d.error)return '';const titles={csv:'We couldn’t validate this CSV.',coverage:'There aren’t enough reviews in this reporting window.',feedback:'There isn’t enough useful feedback.',fee_evidence:'A recurring fee issue could not be established.',sources:'Official fee sources could not be verified.',outputs:'The outputs need validation.',analysis:'Analysis needs attention.'};return `<section class="card space-bottom"><div class="row space-bottom"><span class="icon-box">${icon('info')}</span><h2>${titles[d.error_kind]||'This analysis needs attention.'}</h2></div>${note(d.error,'amber')}<div class="row wrap space-top">${btn('Change CSV or reporting period','change_dataset','','upload')}${d.mode==='Live'&&d.status==='blocked'?btn('Retry processing','retry_analysis','dark','refresh'):''}</div></section>`;}
  function results(){if(!d.file.name)return `<section class="card empty"><div class="icon-box">${icon('chart')}</div><h2>Your review insights will appear here</h2><p>Upload a public customer-review CSV to find recurring themes, understand fee confusion, and prepare your weekly update.</p>${btn('Upload reviews CSV','change_dataset','dark','upload')}</section>`;return `${datasetBar()}${d.notice?`<div class="space-top">${note(d.notice)}</div>`:''}<div class="space-top">${metrics()}</div>${errorPanel()}${a?`<div class="results-grid"><div class="stack">${themes()}${feeCard()}${quotes()}</div><div class="stack">${o?outputPanel():`<section class="card empty"><div class="icon-box">${icon('file')}</div><h2>Outputs ${d.status==='processing'?'are being prepared':'are unavailable'}</h2><p>${d.status==='processing'?'The weekly pulse, fee explanation and email preview appear after source and evidence checks.':'Both required outputs must pass the evidence and source checks before approval.'}</p></section>`}${o?approval():''}</div></div>`:progressCard()}`;}
  function progressCard(){const p=d.processing;const stage=p?.stage||1,done=d.status==='ready',running=d.status==='processing',blocked=d.status==='blocked'||d.status==='invalid';const pct=p?Math.round(p.progress*100):0;return `<section class="card progress-card"><div class="card-header"><div><div class="row"><h2>Automated Orchestrator</h2>${badge(done?'Complete':running?'Running':blocked?'Needs attention':d.status==='cancelled'?'Cancelled':'Ready',done||running?'mint':'')}</div><p class="small muted space-top">Review analysis and source verification</p></div><div class="progress-percent">${num(pct)}%<small>${running?'Elapsed: '+p.elapsed+'s':done?'Checks passed':'Awaiting valid input'}</small></div></div><div class="progress-track"><div style="width:${pct}%"></div></div>${[['Checking Reviews','CSV validation, date filtering and duplicate review ID removal.','check'],['Analyzing Feedback','Identifying themes, exact customer quotes and recurring fee confusion.','light'],['Preparing Outputs','Verifying official sources and preparing the pulse, explanation and email preview.','hourglass']].map(([label,desc,ico],i)=>{const completed=!!d.metrics.included_count&&(done||i+1<stage||i===0),active=running&&i+1===stage&&!completed;return `<div class="pipeline-step ${completed?'complete':active?'active':'waiting'}"><span class="step-icon">${icon(completed?'check':ico)}</span><div class="grow"><div class="row between"><h3>${i+1}. ${label}</h3>${badge(completed?'Completed':active?'Processing':blocked&&i+1===stage?'Blocked':'Waiting',active?'mint':'')}</div><p>${desc}</p>${active?`<div class="step-message">${icon('terminal')}${esc(p.message)}</div>`:''}${i===0&&d.dataset!==null&&m.included_count!=null?`<p class="green">${num(m.included_count)} valid in window · ${num(exclusions)} excluded</p>`:''}</div></div>`;}).join('')}<div class="notice space-top">${icon('check')}<span>${running?'Processing continues while you inspect another workspace tab.':done?'Analysis complete. Review the results before approving external saves.':'A valid upload starts analysis automatically.'}</span></div></section>`;}
  function periodCard(){return `<section class="card"><div class="card-header"><div class="row"><span class="icon-box">${icon('calendar')}</span><h2>Reporting Period Window</h2></div><span class="small">UTC+05:30 (IST)</span></div><div class="period-row"><span>Rolling cadence:</span><div class="segmented">${[8,10,12].map(n=>`<button data-weeks="${n}" class="${Number(d.period.weeks)===n?'active':''}" ${x.saving?'disabled':''}>${n} Weeks</button>`).join('')}</div></div><div class="date-grid"><label><span class="field-label">START WINDOW</span><input class="date-field" id="start-date" type="date" aria-label="Start reporting date" value="${d.period.start}" max="${d.today}" ${x.saving?'disabled':''}></label><label><span class="field-label">END WINDOW</span><input class="date-field" id="end-date" type="date" aria-label="End reporting date" value="${d.period.end}" max="${d.today}" ${x.saving?'disabled':''}></label></div><div class="period-note">${icon('info')}<div><strong>Active window: ${periodText}</strong> ${badge(d.period.weeks+' weeks','mint')}<p>Changing the period after analysis requires recalculation and fresh approval.</p></div></div><div id="period-confirm" ${ui.periodDirty?'':'hidden'} class="confirm-period"><strong>Apply the new reporting period?</strong><p>Existing results will be recalculated. Previous approval will not apply.</p><div class="row">${btn('Keep current period','cancel_period','tiny')}${btn(d.file.name?'Apply and recalculate':'Apply period','apply_period','dark tiny')}</div></div></section>`;}
  function uploadCard(){return `<section class="card"><div class="card-header"><div class="row"><span class="icon-box">${icon('upload')}</span><h2>Feedback Export Ingestion</h2></div>${btn('Schema specs →','schema','ghost tiny')}</div><div class="dropzone" id="dropzone"><div class="upload-icon">${icon('upload')}</div><h2>Drag &amp; drop your customer reviews CSV</h2><p>One public Google Play or App Store review CSV.<br>Required columns are checked automatically (.csv only, max 15 MB).</p><input type="file" accept=".csv,text/csv" id="csv-file" class="hidden-input" aria-label="Upload reviews CSV" ${x.saving?'disabled':''}><div class="row wrap">${btn('Browse files','browse','dark','folder',x.saving?'disabled':'')}${btn('Sample .csv','sample','','download')}</div>${d.file.name?`<div class="file-staged"><span class="icon-box">${icon('table')}</span><div class="grow"><div class="file-name">${esc(d.file.name)}</div><div class="muted">${bytes(d.file.bytes)}${m.original_count!=null?' · '+num(m.original_count)+' reviews':''}</div></div>${badge(d.status==='invalid'?'Invalid':d.status==='ready'?'Analyzed':'Loaded',d.status==='invalid'?'red':'mint')}</div>`:''}</div><div class="immutable"><span class="icon-box">${icon('lock')}</span><div><strong>Original upload preserved</strong><p>Validation and filtering are applied to a separate analysis view. The original CSV text, dates, and source URLs stay intact.</p>${btn('CSV formatting requirements &amp; sample template ↗','schema','ghost')}</div></div></section>`;}
  function rulesCard(){return `<section class="card"><div class="card-header"><div class="row"><span class="icon-box">${icon('table')}</span><h2>Validation &amp; Coverage Rules</h2></div><span class="eyebrow">Backend checks</span></div><p class="small muted">The same evidence and approval rules apply to every upload.</p><div class="rule"><span></span><div><h3>Valid CSV Payload</h3><p>Required columns, ISO dates, ratings and public source URLs are verified before analysis starts.</p></div></div><div class="rule"><span style="background:#575e70"></span><div><h3>Reporting Window</h3><p>Only unique valid reviews inside the selected 8–12 week period contribute to the analysis. Exclusions remain inspectable.</p></div></div><div class="rule"><span style="background:#7c8a82"></span><div><h3>Specific Fee Evidence</h3><p>At least three distinct review texts must support the same named fee confusion. Insufficient evidence blocks the fee explanation and approval.</p></div></div><div class="divider"></div><div class="row between small green"><span class="row">${icon('shield')}Original review traceability</span>${btn('Inspect data quality','open_audit','ghost tiny')}</div></section>`;}
  function upload(){return `<div class="page-heading"><div><div class="row">${badge('Review ingestion','mint')}<span class="eyebrow">CSV → Product insights</span></div><h1>Upload &amp; Processing Pipeline</h1><p>Select a reporting period and upload customer reviews for automatic analysis.</p></div><div class="engine-chip"><div><span class="eyebrow">Analysis engine</span><div>OpenAI · Structured outputs</div></div><span class="split"></span><div><span class="eyebrow">Execution</span><div>On demand · Approval gated</div></div><i class="dot"></i></div></div>${d.notice?`<div class="space-bottom">${note(d.notice)}</div>`:''}${errorPanel()}<div class="upload-grid"><div class="stack">${periodCard()}${uploadCard()}</div><div class="stack">${progressCard()}${rulesCard()}</div></div><div class="upload-bottom"><div class="row"><span class="icon-box">${icon('sparkle')}</span><div><h3>Automatically prepare the weekly pulse and fee explanation</h3><p>Completed results appear in the Results Workspace for your review.</p></div></div><div class="row">${d.status==='processing'?btn('Cancel processing','cancel'):''}${btn('Go to Workspace','open_results','dark','arrow')}</div></div>`;}
  const labels={duplicate:'Duplicate ID',invalid:'Invalid record',outside:'Out of window',future:'Future-dated',nonspecific:'Nonspecific feedback'};
  function auditPage(){if(!d.file.name)return `<section class="card empty"><div class="icon-box">${icon('shield')}</div><h2>Data quality starts with your CSV</h2><p>Upload a review file to inspect duplicate IDs, invalid rows, date exclusions and the evidence behind the insights.</p>${btn('Upload reviews CSV','change_dataset','dark','upload')}</section>`;return `<section class="audit-hero"><div class="page-heading"><div><div class="row">${badge('<i class="dot"></i>Deterministic validation')}<span class="mono">Original upload preserved</span></div><h1>Evidence &amp; Data Quality Audit Panel</h1><p>Inspect cleaning decisions, fee confusion evidence, and official verification sources.</p></div><div class="row">${btn('Download Excluded (.csv)','download','','download','data-kind="excluded" '+(m.original_count?'':'disabled'))}${btn('Run Hash Verification','verify_hash','primary','shield')}</div></div>${d.notice?`<div class="space-bottom">${note(d.notice)}</div>`:''}<div class="audit-metrics">${[['Total excluded records',num(exclusions),'/ '+num(m.original_count)+' uploaded rows','Original file preserved'],['Schema & timestamp',num(m.invalid_count),'invalid rows','Validity is checked before de-duplication'],['Duplicate ID check',num(m.duplicate_count),'duplicate IDs','Same platform + review ID'],['Outside reporting window',num((m.outside_window_count||0)+(m.future_count||0)),'date exclusions',num(m.future_count||0)+' after end date']].map(v=>`<div class="audit-metric"><div class="eyebrow">${v[0]}</div><div class="value">${v[1]} <small>${v[2]}</small></div><p>${v[3]}</p></div>`).join('')}</div><div class="cascade"><span class="icon-box">${icon('table')}</span><div><h3>Deterministic Cascade Guarantee</h3><p>One primary exclusion reason per row. No excluded record is counted twice.</p></div><div class="cascade-chain"><span>Invalid<br>(${num(m.invalid_count||0)})</span>${icon('arrow')}<span>Duplicate ID<br>(${num(m.duplicate_count||0)})</span>${icon('arrow')}<span>Outside window<br>(${num((m.outside_window_count||0)+(m.future_count||0))})</span><strong class="small green">Σ = ${num(exclusions)}</strong></div></div></section><section class="card"><div class="audit-controls"><div><h2>Audit Log &amp; Exclusion Inspector</h2><p>Inspect original rows and their final filtering reason. Nonspecific feedback remains valid for count reconciliation.</p></div><div class="audit-filters" aria-label="Audit categories">${[['all','All exclusions',exclusions],['invalid','Invalid records',audit.counts.invalid],['duplicate','Duplicate IDs',audit.counts.duplicate],['outside','Out of window',audit.counts.outside],['future','Future dates',audit.counts.future],['nonspecific','Nonspecific retained',audit.counts.nonspecific]].map(([id,label,n])=>`<button data-filter="${id}" class="${audit.filter===id?'active':''}">${label} (${num(n)})</button>`).join('')}</div></div><div class="audit-search"><label class="search-input">${icon('search')}<input id="audit-search" aria-label="Search audit records" placeholder="Search by review ID, text snippet, or hash…" value="${esc(audit.search)}"></label><span class="count">Displaying ${num(audit.rows.length)} of ${num(audit.filtered_count)} records</span>${btn('Original Hash Check','verify_hash','tiny','fingerprint')}</div><div class="table-wrap"><table class="audit-table"><thead><tr><th>Review ID</th><th>Date</th><th>Exclusion reason</th><th>Customer review excerpt</th><th>Text fingerprint</th><th>Actions</th></tr></thead><tbody>${audit.rows.length?audit.rows.map((r,i)=>`<tr><td class="review-id">${esc(r.review_id||'CSV row '+r.row)}</td><td>${/^\d{4}-\d{2}-\d{2}$/.test(r.date)?date(r.date):`<span class="red">${esc(r.date||'Missing date')}</span>`}</td><td>${badge(esc(labels[r.category]||r.category),r.category==='invalid'?'red':r.category==='nonspecific'?'mint':'')}</td><td class="excerpt">“${esc(r.review_text.slice(0,100))}${r.review_text.length>100?'…':''}”</td><td><span class="hash">${esc(r.text_hash.slice(0,8))}…${esc(r.text_hash.slice(-4))} ✓</span></td><td><button class="row-action" data-row="${i}" aria-label="Inspect review ${esc(r.review_id||r.row)}">${icon('eye')}</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${m.original_count?'No matching records in this category.':'The uploaded CSV could not be parsed into valid audit records.'}</div></td></tr>`}</tbody></table></div><div class="pagination"><span>${audit.filter==='nonspecific'?'These reviews are valid, but excluded from theme counts and quote selection.':'Each row has one recorded primary exclusion reason.'}</span><div class="row">${btn('Previous','page_previous','tiny','',audit.page<=1?'disabled':'')}<span class="current">${audit.page}</span><span>of ${audit.pages}</span>${btn('Next','page_next','tiny','',audit.page>=audit.pages?'disabled':'')}</div></div></section><div class="audit-bottom">${auditFee()}${auditSources()}${auditExecution()}</div>`;}
  function auditFee(){return `<section class="card"><div class="card-header"><div class="row"><span class="icon-box mint">${icon('rupee')}</span><h2>Customer Review Fee Evidence</h2></div>${badge(a?.fee_evidence.length?'Traceable':'Pending',a?.fee_evidence.length?'mint':'')}</div><p class="small muted">${a?.fee_name?'Selected fee: '+esc(a.fee_name):'A named recurring fee has not been established.'}</p><div class="source-card"><span class="metric-value">${num(a?.fee_evidence.length||0)}</span><p>Distinct original review texts supporting the selected fee issue. Repeated wording does not establish independent evidence.</p></div>${(a?.fee_evidence||[]).slice(0,2).map(q=>`<div class="evidence-quote"><div class="row between"><strong class="green mono">${esc(q.review_key)}</strong><span class="small muted">${date(q.date)}</span></div><p>“${esc(q.selected_fee_passage)}”</p></div>`).join('')}<div class="divider"></div>${btn('View all fee evidence →','fee_evidence','ghost tiny')}</section>`;}
  function auditSources(){return `<section class="card"><div class="card-header"><div class="row"><span class="icon-box mint">${icon('shield')}</span><h2>Official Verified Sources</h2></div>${badge((o?.sources.length||0)+' sources')}</div><p class="small muted">Official fee facts; separate from customer reports.</p>${o?.sources.map(s=>`<div class="source-card"><div class="row between"><h3>${esc(s.title)}</h3>${badge('Checked','mint')}</div>${anchor(new URL(s.url).hostname,s.url,'','')}<p>Last checked: ${esc(s.checked_at)}</p></div>`).join('')||`<div class="empty small">Official sources are shown after retrieval and output validation.</div>`}<div class="divider"></div>${btn('Inspect source passages →','official_sources','ghost tiny')}</section>`;}
  function auditExecution(){return `<section class="card"><div class="card-header"><div class="row"><span class="icon-box">${icon('lock')}</span><h2>Execution &amp; Write Audit Status</h2></div>${badge(x.completed?'Completed':'Approval gated',x.completed?'mint':'')}</div><p class="small muted">External actions require approval of the current outputs.</p>${[['Google Docs Append','append_product_update'],['Gmail Unsent Draft','create_support_draft']].map(([label,key])=>`<div class="audit-state"><div class="row between"><strong>${label}</strong><span class="green">${esc(x.states[key]?.status||'Not started')}</span></div><p>${key==='create_support_draft'?'Recipient stays blank. No email-send operation exists.':'The configured document is appended once per approved snapshot.'}</p></div>`).join('')}<div class="notice error space-top">${icon('shield')}<span>Reject performs no external writes. Uncertain outcomes must be checked before retrying.</span></div><div class="divider"></div>${btn('Inspect approval status →','open_results','ghost tiny')}</section>`;}
  function drawer(){if(!ui.drawer)return '';let title='',subtitle='',body='';
    if(ui.drawer==='schema'){title='CSV formatting requirements';subtitle='Use the existing review data contract';body=`<div class="requirements"><p>Upload one UTF-8 CSV, at most 15 MB and 50,000 rows.</p><div class="divider"></div><p>Required columns:</p><p>${['platform','review_id','date','rating','review_text','source_url'].map(s=>`<code>${s}</code>`).join(' ')}</p><ul><li>Dates: YYYY-MM-DD.</li><li>Ratings: whole numbers from 1 to 5.</li><li>Source URLs: original public HTTPS review links.</li><li>Review text: preserve the original wording.</li><li>The reporting window must cover 8–12 weeks.</li></ul><div class="divider"></div><p>Generic comments such as “good” or “bad” are excluded from themes. Short specific feedback such as “hidden charges” stays eligible.</p><div class="space-top">${btn('Download sample CSV','sample','dark','download')}</div></div>`;}
    else if(ui.drawer==='about'){title='Groww Review Intelligence';subtitle='Product + support review workspace';body=`${note('API keys, n8n bearer authentication, and Google credentials are handled on the server.')}<div class="divider"></div><div class="requirements"><p>Upload → validated review insights → weekly pulse and fee explanation → your approval → Google Docs and Gmail draft.</p><p class="space-top">Saving always requires your explicit approval of the current content.</p><p class="space-top">Changing tabs, opening evidence, copying, and downloading never initiate external writes.</p></div>`;}
    else if(ui.drawer==='row'){const r=audit.rows[ui.rowIndex];if(r){title=r.review_id||'CSV row '+r.row;subtitle=labels[r.category]+' · '+(r.platform||'Unknown platform');body=`${badge(esc(labels[r.category]),r.category==='invalid'?'red':'')}<div class="full-review">${esc(r.review_text)}</div><div class="detail-row"><span>Review date</span><strong>${esc(r.date||'Missing')}</strong></div><p class="small">${esc(r.reason)}</p><div class="divider"></div><div class="eyebrow">Normalized text fingerprint</div><p class="mono space-top">${esc(r.text_hash)}</p>${r.source_url?`<div class="space-top">${anchor('Open original review source',r.source_url)}</div>`:''}`;}}
    else if(ui.drawer==='theme'){const t=a?.themes.find(v=>v.id===ui.themeId);if(t){title=t.name;subtitle=num(t.count)+' distinct review IDs · one primary theme per review';body=`<p class="small muted">${esc(t.description)}</p>${t.supporting.map(q=>quoteCard({...q,theme_id:t.id})).join('')}<div class="divider"></div><p class="small muted">Showing up to 20 original supporting reviews. Download all classifications for the complete mapping.</p>${btn('Download classifications','download','dark tiny','download','data-kind="classifications"')}`;}}
    else if(ui.drawer==='evidence'){title='Fee evidence & official sources';subtitle=a?.fee_issue||'Review evidence and official facts';body=`<div class="drawer-tabs"><button data-evidence="reviews" class="${ui.evidenceTab==='reviews'?'active':''}">Customer review evidence</button><button data-evidence="sources" class="${ui.evidenceTab==='sources'?'active':''}">Official fee sources</button></div>${ui.evidenceTab==='reviews'?`<p class="small muted">${esc(shortDescription(a?.fee_rationale||'No recurring named fee has been established.'))}</p>${a?.fee_rationale?`<details><summary>Full analysis rationale</summary><div class="detail-inner small">${esc(a.fee_rationale)}</div></details>`:''}<p class="small muted space-top">At least three distinct original review texts are required.</p>${(a?.fee_evidence||[]).map(q=>`<article class="quote"><div class="meta"><strong class="green">${esc(q.review_key)}</strong><span>${date(q.date)}</span></div><div class="full-review">${esc(q.text)}</div><p class="small"><strong>Named fee passage:</strong> “${esc(q.selected_fee_passage)}”</p>${anchor('View original source',q.source_url,'','external')}</article>`).join('')}`:`<p class="small muted">These official pages support the fee facts. Customer reviews establish the recurring misunderstanding.</p>${(o?.sources||[]).map(s=>`<article class="source-card"><h3>${esc(s.title)}</h3>${anchor(s.url,s.url,'','external')}<p>Last checked: ${esc(s.checked_at)}</p></article>`).join('')}${(o?.grounding||[]).map((g,i)=>`<details><summary>Bullet ${i+1}: matched official passages</summary><div class="detail-inner"><p class="small">${esc(g.text)}</p>${g.supporting_passages.map(p=>`<blockquote class="source-passages">${esc(p)}</blockquote>`).join('')}</div></details>`).join('')}`}`;}
    return `<div class="scrim" data-overlay="close"><aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-head"><div><h2>${esc(title)}</h2><p class="small muted space-top">${esc(subtitle)}</p></div><button class="drawer-close" data-action="close_drawer" aria-label="Close details">${icon('close')}</button></div><div class="drawer-content">${body}</div><div class="drawer-foot">Original customer wording · Traceable evidence · No external writes from this panel</div></aside></div>`;
  }
  function render(){
    const drawerScroll=root.querySelector('.drawer-content')?.scrollTop||0;
    const wasDrawerOpen=!!root.querySelector('.drawer');
    const searchInput=root.querySelector('#audit-search');
    const active=!!searchInput && searchInput===parentElement.activeElement;
    const selection=active?searchInput.selectionStart:null;
    root.innerHTML=`<div class="app">${header()}<main class="content">${ui.nav==='results'?results():ui.nav==='audit'?auditPage():upload()}</main>${footer()}</div>${drawer()}`;
    bind();
    const drawerContent=root.querySelector('.drawer-content');
    if(drawerContent)drawerContent.scrollTop=drawerScroll;
    if(ui.drawer&&!wasDrawerOpen)root.querySelector('.drawer-close')?.focus();
    if(active){const input=root.querySelector('#audit-search');input?.focus();input?.setSelectionRange(selection,selection);}
  }
  function redraw(){ui.forceRender=true;render();}
  function beginUpload(file){
    if(!file || x.saving)return;
    if(!file.name.toLowerCase().endsWith('.csv')||file.size>15*1024*1024||file.size===0){toast('Choose a nonempty CSV of at most 15 MB.');return;}
    const period=selectedPeriod();
    if(new Date(period.end+'T12:00:00')>new Date(d.today+'T12:00:00')){toast('The reporting end date cannot be in the future.');return;}
    const days=Math.round((new Date(period.end+'T12:00:00')-new Date(period.start+'T12:00:00'))/86400000)+1;
    if(days<56||days>84){toast('Choose a reporting window of 8–12 weeks.');return;}
    const reader=new FileReader(),readId=crypto.randomUUID();ui.readId=readId;
    reader.onerror=()=>toast('This file could not be read. Choose it again.');
    reader.onload=()=>{if(ui.readId!==readId)return;ui.nav='upload';ui.awaitingResults=true;ui.periodDirty=false;emit('upload',{name:file.name,content:String(reader.result).split(',')[1],...period});};
    reader.readAsDataURL(file);toast('Reading CSV…');
  }
  function bind(){
    root.onclick=async e=>{
      const nav=e.target.closest('[data-nav]');if(nav){ui.nav=nav.dataset.nav;ui.drawer=null;redraw();scrollTop();return;}
      const tab=e.target.closest('[data-output]');if(tab){ui.tab=tab.dataset.output;redraw();return;}
      const theme=e.target.closest('[data-theme]');if(theme){ui.drawer='theme';ui.themeId=theme.dataset.theme;redraw();return;}
      const row=e.target.closest('[data-row]');if(row){ui.drawer='row';ui.rowIndex=Number(row.dataset.row);redraw();return;}
      const evidence=e.target.closest('[data-evidence]');if(evidence){ui.evidenceTab=evidence.dataset.evidence;redraw();return;}
      const filter=e.target.closest('[data-filter]');if(filter){emit('audit_filter',{filter:filter.dataset.filter,search:audit.search,page:1});return;}
      const weeks=e.target.closest('[data-weeks]');if(weeks){const end=root.querySelector('#end-date').value;const start=new Date(end+'T12:00:00');start.setDate(start.getDate()-Number(weeks.dataset.weeks)*7+1);root.querySelector('#start-date').value=start.toISOString().slice(0,10);ui.periodDirty=true;root.querySelector('#period-confirm').hidden=false;return;}
      if(e.target.dataset.overlay==='close'){ui.drawer=null;redraw();return;}
      const button=e.target.closest('[data-action]');if(!button||button.disabled)return;
      const action=button.dataset.action;
      if(['about','schema'].includes(action)){ui.drawer=action;redraw();}
      else if(action==='close_drawer'){ui.drawer=null;redraw();}
      else if(action==='browse')root.querySelector('#csv-file')?.click();
      else if(action==='sample')download('groww_reviews_sample.csv',d.sample_csv,'text/csv');
      else if(action==='change_dataset'){ui.nav='upload';ui.editing=false;redraw();scrollTop();}
      else if(action==='open_results'){ui.nav='results';redraw();scrollTop();}
      else if(action==='open_audit'){ui.nav='audit';redraw();scrollTop();}
      else if(action==='new'){ui.nav='upload';ui.periodDirty=false;emit('new');}
      else if(action==='apply_period'){ui.periodDirty=false;emit('period',selectedPeriod());}
      else if(action==='cancel_period'){ui.periodDirty=false;redraw();}
      else if(action==='fee_evidence'||action==='official_sources'){ui.drawer='evidence';ui.evidenceTab=action==='official_sources'?'sources':'reviews';redraw();}
      else if(action==='edit'){ui.editing=true;ui.draft=o.weekly_pulse;ui.editRevision=o.edit_revision;redraw();root.querySelector('#pulse-editor')?.focus();}
      else if(action==='cancel_edit'){ui.editing=false;redraw();}
      else if(action==='save_edit'){ui.draft=root.querySelector('#pulse-editor').value;ui.editing=false;emit('edit',{text:ui.draft,revision:ui.editRevision});}
      else if(action==='copy'){
        const feeText=o.fee_faq_markdown;
        const text=ui.tab==='pulse'?o.weekly_pulse:ui.tab==='fee'?feeText:'Subject: '+o.email.subject+'\n\n'+o.email.body;
        try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{toast('Clipboard access is unavailable. Use Export to save a copy.');}
      }
      else if(action==='export'){const file=button.dataset.file;download(file,ui.tab==='fee'?o.fee_faq_markdown:o.downloads[file]);}
      else if(action==='download')emit('download',{kind:button.dataset.kind});
      else if(action==='page_previous'||action==='page_next')emit('audit_filter',{filter:audit.filter,search:audit.search,page:audit.page+(action==='page_next'?1:-1)});
      else if(action==='approve'||action==='retry_save'){
        button.disabled=true;button.textContent='Saving approved outputs…';emit(action,{fingerprint:x.fingerprint});
      }
      else if(['reject','reconcile','cancel','retry_analysis','verify_hash','regenerate'].includes(action))emit(action);
    };
    root.onkeydown=e=>{if(e.key==='Escape'&&ui.drawer){ui.drawer=null;redraw();}};
    root.onchange=e=>{if(e.target.id==='csv-file')beginUpload(e.target.files[0]);if(e.target.id==='start-date'||e.target.id==='end-date'){ui.periodDirty=true;root.querySelector('#period-confirm').hidden=false;}};
    root.oninput=e=>{
      if(e.target.id==='pulse-editor'){ui.draft=e.target.value;const words=ui.draft.trim().split(/\s+/).filter(Boolean).length;const count=root.querySelector('#editor-count');count.textContent=words+'/250 words'+(words>250?' · '+(words-250)+' over the limit':'');count.classList.toggle('red',words>250);}
      if(e.target.id==='audit-search'){clearTimeout(ui.searchTimer);const value=e.target.value;ui.searchTimer=setTimeout(()=>emit('audit_filter',{filter:audit.filter,search:value,page:1}),400);}
    };
    const drop=root.querySelector('#dropzone');
    if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging');};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');beginUpload(e.dataTransfer.files[0]);};}
  }
  render();
  if(d.download&&ui.lastDownload!==d.download.id){let previousDownload=null;try{previousDownload=sessionStorage.getItem('groww-last-download');}catch{}ui.lastDownload=d.download.id;if(previousDownload!==d.download.id){try{sessionStorage.setItem('groww-last-download',d.download.id);}catch{}download(d.download.name,d.download.content,d.download.mime);}}
}
